var a = [2, 6, 9];
var b = [1, 3, 4, 8];
var merged = [];
var i = 0;
var j = 0;
while (i < a.length && j < b.length) {
  merged.push(a[i] <= b[j] ? a[i++] : b[j++]);
}
console.log(merged.concat(a.slice(i), b.slice(j)));
